# The steps of the API contract test (recorded from the original CMS by
# record_api.py, replayed against ours by TestCMSAPI in api_test.go).
# SQL runs before the request, on whichever database the site uses; rows
# are found by name so it works on both. auth: "" (none), or the name a
# previous step saved its login_data under (sent in X-CMS-Authorization).
SUM = "4926046975063954292"     # alice's submission on sum (GroupMin)
HALF = "1111111111111111111"    # alice's submission on half (Sum)
BOB = "8732919409223706904"     # bob's submission on sum
ALICE_P = "(SELECT p.id FROM participations p JOIN users u ON u.id = p.user_id WHERE u.username = 'alice')"
SUM_SUB = f"(SELECT id FROM submissions WHERE opaque_id = {SUM})"
RESET = [
    "UPDATE groups SET start = '2025-01-01 00:00:00+00', stop = '2030-01-01 00:00:00+00', analysis_enabled = false, "
    "analysis_start = '2100-01-01 00:00:00+00', analysis_stop = '2100-01-01 00:00:00+00', per_user_time = NULL",
    "UPDATE contests SET ip_restriction = true, block_hidden_participations = false, min_submission_interval = NULL, "
    "max_submission_number = NULL",
    "UPDATE tasks SET feedback_level = 'restricted', max_submission_number = NULL, min_submission_interval = NULL",
    "UPDATE participations SET ip = NULL, hidden = false, unrestricted = false",
]

def step(name, method, path, auth="", form=None, files=None, sql=None, save=None, check=None):
    return {k: v for k, v in dict(name=name, method=method, path=path, auth=auth, form=form or {},
                                  files=files or [], sql=sql or [], save=save, check=check).items()
            if v not in (None, [], {}, "")} | {"method": method, "path": path}

